@code {
    [Parameter, EditorRequired] public List<ReferenceModel> Entries { get; set; } = [];
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void UpdateEntry(int index, ReferenceModel updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry()
    {
        if (Entries.Count < 3)
        {
            Entries.Add(new ReferenceModel());
        }
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ValidationError = null;

        if (Entries.Count < 2)
        {
            ValidationError = "Please provide at least 2 references.";
            return;
        }

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Name) ||
                string.IsNullOrWhiteSpace(entry.Relationship) ||
                string.IsNullOrWhiteSpace(entry.Email))
            {
                ValidationError = "Please fill in Name, Relationship, and Email for all references.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}
