@namespace sv_147c019210d74ee7ae320b0d3c4181f8.Components.Pages.Apply

<section class="step-panel">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter below:</label>
        <textarea rows="12" class="cover-letter-input"
                  @bind="CoverLetterText"
                  @bind:event="oninput"
                  maxlength="@MaxLength"></textarea>
        <div class="char-count @(CoverLetterText.Length > MaxLength ? "over-limit" : "")">
            @CoverLetterText.Length / @MaxLength characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetterText { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterTextChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task HandleNext()
    {
        ValidationError = null;

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ValidationError = "Please write a cover letter.";
            return;
        }

        await CoverLetterTextChanged.InvokeAsync(CoverLetterText);
        await OnNext.InvokeAsync();
    }
}

