@page "/apply"
@namespace sv_147c019210d74ee7ae320b0d3c4181f8.Components.Pages.Apply
@using sv_147c019210d74ee7ae320b0d3c4181f8.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   StepNames="@stepNames"
                   OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@personalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep Entries="@references"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep @bind-CoverLetterText="coverLetter"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnBack="PreviousStep"
                        OnEditSection="GoToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private static readonly List<string> stepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    private int currentStep;
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void NextStep() => currentStep = Math.Min(currentStep + 1, stepNames.Count - 1);
    private void PreviousStep() => currentStep = Math.Max(currentStep - 1, 0);
    private void GoToStep(int step) => currentStep = step;

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    min-width: 80px;
    transition: opacity 0.2s;
}

.step-indicator .step.future {
    opacity: 0.4;
    cursor: not-allowed;
}

.step-indicator .step.active .step-number {
    background: #4361ee;
    color: white;
    font-weight: bold;
}

.step-indicator .step.completed .step-number {
    background: #2ec4b6;
    color: white;
}

.step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e0e0e0;
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 0.25rem;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #333;
}

.step-connector {
    width: 30px;
    height: 2px;
    background: #e0e0e0;
    align-self: flex-start;
    margin-top: 18px;
}

.step-connector.completed {
    background: #2ec4b6;
}

.checkmark {
    font-weight: bold;
}

/* Step Panel */
.step-panel {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.step-panel h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
    border-bottom: 2px solid #4361ee;
    padding-bottom: 0.5rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #333;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: normal !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Fieldsets */
fieldset.work-entry-form,
fieldset.reference-form {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

fieldset legend {
    font-weight: 600;
    color: #4361ee;
    padding: 0 0.5rem;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn-primary {
    background: #4361ee;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #3451d1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: white;
    color: #4361ee;
    border: 1px solid #4361ee;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-outline:hover {
    background: #f0f4ff;
}

.btn-secondary {
    background: #f8f9fa;
    color: #333;
    border: 1px solid #ddd;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e9ecef;
}

.btn-danger {
    background: #fff;
    color: #dc3545;
    border: 1px solid #dc3545;
    padding: 0.4rem 0.8rem;
    border-radius: 4px;
    font-size: 0.85rem;
    cursor: pointer;
}

.btn-danger:hover {
    background: #dc3545;
    color: white;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

/* Validation */
.validation-error {
    background: #fff3f3;
    border: 1px solid #ffcdd2;
    color: #c62828;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
}

.field-error {
    color: #c62828;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

/* Cover Letter */
.cover-letter-input {
    min-height: 200px;
    font-family: inherit;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #c62828;
    font-weight: bold;
}

/* Review Step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #eee;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h3 {
    margin: 0 0 0.5rem 0;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #555;
}

.review-section dd {
    margin: 0;
}

.review-item {
    padding: 0.5rem 0;
}

.review-item + .review-item {
    border-top: 1px solid #f0f0f0;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    max-height: 200px;
    overflow-y: auto;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h3 {
    color: #2ec4b6;
    font-size: 1.5rem;
}

