<fieldset class="reference-form">
    <legend>Reference @(Index + 1)</legend>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Entry.Name" @onchange="OnNameChanged" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Entry.Relationship" @onchange="OnRelationshipChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email" @onchange="OnEmailChanged" />
        </div>

        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Entry.Phone" @onchange="OnPhoneChanged" />
        </div>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private Task OnNameChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Name = (string?)e.Value ?? "" });

    private Task OnRelationshipChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Relationship = (string?)e.Value ?? "" });

    private Task OnEmailChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Email = (string?)e.Value ?? "" });

    private Task OnPhoneChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Phone = (string?)e.Value ?? "" });
}

