<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@IsCurrent"
                   @onchange="OnEndDateChanged" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="OnIsCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="OnDescriptionChanged"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private Task OnCompanyChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Company = (string?)e.Value ?? "" });

    private Task OnTitleChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Title = (string?)e.Value ?? "" });

    private Task OnStartDateChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { StartDate = DateTime.TryParse((string?)e.Value, out var d) ? d : DateTime.Today });

    private Task OnEndDateChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null });

    private Task OnIsCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool?)e.Value ?? false;
        return OnEntryChanged.InvokeAsync(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }

    private Task OnDescriptionChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Description = (string?)e.Value ?? "" });
}

